fn put(o:[*]u8,p:usize,x:f64)void{const bits:u64=@bitCast(x);for(0..8)|k|o[p+k]=@truncate(bits>>@intCast(8*k));}
fn absf(x:f64)f64{return if(x<0)-x else x;}
export fn gaussian_elimination_pivoting(v:[*c]const i64,n:usize,o:[*c]u8,cap:usize)i64{if(v==null or n<1 or n>21)return -1;const dr=v[0];if(dr<2 or dr>4)return -1;const d:usize=@intCast(dr);if(n!=1+d*(d+1))return -1;var a=[_] [5]f64{.{0} ** 5} ** 4;for(0..d)|i|{for(0..d+1)|j|{const z=v[1+i*(d+1)+j];if(z < -10000 or z>10000)return -1;a[i][j]=@as(f64,@floatFromInt(z))/1000.0;}}const bytes=d*8;for(0..d)|col|{for(col..d)|i|{if(absf(a[i][col])>absf(a[col][col])){const temp=a[col];a[col]=a[i];a[i]=temp;}}if(absf(a[col][col])<1e-8)return -1;if(col!=0){const prior=col-1;for(col..d)|i|{const factor=a[i][prior]/a[prior][prior];for(0..d+1)|j|a[i][j]-=factor*a[prior][j];}}}var x=[_]f64{0} ** 4;var col=d;while(col>0){col-=1;x[col]=a[col][d]/a[col][col];var i=col;while(i>0){i-=1;a[i][d]-=a[i][col]*x[col];}}if(o==null or cap<bytes)return -2;for(0..d)|i|put(o,i*8,x[i]);return @intCast(bytes);}
